import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;
import java.io.PrintWriter;
import java.io.BufferedWriter;
import java.io.OutputStreamWriter;
import java.util.StringTokenizer;

public class Main {
    static class FastReader {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer("");
        String next() {
            while (!st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }
        int nextInt() {
            return Integer.parseInt(next());
        }
        long nextLong() {
            return Long.parseLong(next());
        }
        String nextString() {
            return next();
        }
    }

    public static void main(String[] args) {
        FastReader fr = new FastReader();
        PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));
        int T = 1;
        for (int t = 0; t < T; t++) {
            Solution s = new Solution(out, fr);
            s.solve(T, t);
        }
        out.flush();
    }
}

class Solution {
    PrintWriter out;
    FastReader fr;
    int MOD = 998244353;

    public Solution(PrintWriter out, FastReader fr) {
        this.out = out;
        this.fr = fr;
    }

    public void solve(int total, int index) {
        int n = fr.nextInt();
        int mod = fr.nextInt();

        long[][] dp = new long[n][n * n + 5];
        dp[0][0] = 1;
        for (int i = 1; i < n; i++) {
            for (int j = 0; j < dp[0].length; j++) {
                for (int cnt = 0; cnt <= i; cnt++) {
                    if (j - cnt >= 0) {
                        dp[i][j] += dp[i - 1][j - cnt];
                        dp[i][j] %= mod;
                        if (dp[i][j] == 0) dp[i][j] += mod;
                    }
                }
            }
        }

        long[][] sums = new long[dp.length][dp[0].length];
        for (int i = 0; i < dp.length; i++) {
            long sum = 0;
            for (int j = 0; j < dp[0].length; j++) {
                sum += dp[i][j];
                sum %= mod;
                if (sum == 0) sum += mod;
                sums[i][j] = sum;
            }
        }

        long[] fact = new long[501 * 501];
        fact[0] = 1;
        for (int i = 1; i < fact.length; i++) {
            fact[i] = (fact[i - 1] * i) % mod;
        }

        long[][] ncr = new long[501][501];
        ncr[0][0] = 1;
        for (int i = 1; i < ncr.length; i++) {
            ncr[i][0] = 1;
            for (int j = 1; j <= i; j++) {
                ncr[i][j] = (ncr[i - 1][j] + ncr[i - 1][j - 1]) % mod;
            }
        }

        long result = 0;
        for (int i = 0; i <= n - 2; i++) {
            int cnt = n - i;
            int pre = n - cnt;
            long comb = (ncr[n][pre] * fact[pre]) % mod;
            long totalSum = 0;
            long[] last = dp[cnt - 2];
            long ssum = 0;
            long total = 0;
            for (int j = 2; j < dp[0].length; j++) {
                total += sums[cnt - 2][j - 2] * (cnt - 1);
                total %= mod;
                if (total == 0) total += mod;

                long temp = last[j] * total;
                result += temp;
                result %= mod;

                ssum += sums[cnt - 2][j - 2];
                if (j - cnt - 1 >= 0) {
                    ssum -= sums[cnt - 2][j - cnt - 1];
                }
                ssum = (ssum + mod) % mod;

                total -= ssum;
                total = (total + mod) % mod;
            }
            result += (sum * comb) % mod;
            result %= mod;
        }
        out.println(result);
    }
}
